contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool setAdmin) public payable {
        // Setup: optionally make this contract an admin in c by calling the public state-changing function.
        // isAdmin is a public getter on c; the only way to set it through c's public surface is not available,
        // so derive the expected outcome from whether this contract is already an admin.
        bool adminBefore;
        adminBefore = c.isAdmin(address(this));

        // Deciding call: attempt to call the public entry.
        bool reverted;
        try c.newEmergencyOracle("test") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call completes iff the caller is an admin; otherwise it reverts.
        // (The public getter isAdmin is read-only and c's only public state-changing entry is newEmergencyOracle.)
        assert(reverted == !adminBefore);
    }

    receive() external payable {}
}
